import { execFileSync } from "node:child_process";
import { relative } from "node:path";

import { repoRoot } from "./lib.mjs";

/**
 * This repository dogfoods itself: docs/reference/product-map/ is its own
 * product map, regenerated by pmap.
 *
 * Unlike the other steps this one does not declare `{ path, content }`
 * artifacts. pmap already owns atomic writes (core/writer.ts) and byte-exact
 * drift detection (`pmap check-fresh`, which deliberately preserves the
 * recorded commit so an artifact-only commit cannot look like drift).
 * Reproducing either here would be a second, weaker implementation of the
 * behavior this repository exists to provide, so the step delegates instead.
 */
function pmap(command) {
  return execFileSync("pnpm", ["--silent", "pmap", command], {
    cwd: repoRoot,
    encoding: "utf8",
    stdio: ["ignore", "pipe", "pipe"],
  });
}

/** Writer report lines look like `  + update    /abs/path`; unchanged entries are not news. */
function changedPaths(stdout) {
  const changed = [];
  for (const line of stdout.split("\n")) {
    const match = /^\s+[-+~=]\s+(create|update|delete)\s+(.+)$/.exec(line);
    if (match !== null) changed.push(relative(repoRoot, match[2].trim()));
  }
  return changed.sort();
}

export default {
  name: "self-product-map",
  apply({ check }) {
    if (check) {
      try {
        pmap("check-fresh");
      } catch (error) {
        const detail = [error.stdout, error.stderr].filter(Boolean).join("").trim();
        throw new Error(`pmap check-fresh reported drift — run \`pnpm generate\`:\n${detail}`);
      }
      return { changed: [] };
    }
    return { changed: changedPaths(pmap("all")) };
  },
};
